1	// Acceptance tests for the change request:
2	//   "Let me record what a client has paid on an invoice. Store the amount and the date. Show it on
3	//    the invoice."
4	//
5	// An invoice can now carry a record of what the client has PAID against it. On the invoice's own
6	// detail page (invoice-detail-page, reached by navigating to /invoices/<id> — the same public URL
7	// surface the invoice specs already use) a payments region (invoice-payments) lists every payment
8	// recorded on THAT invoice in a table (invoice-payments-table). Each payment row (payment-row-<id>)
9	// shows the two things stored for it: the AMOUNT paid (payment-amount) and the DATE it was paid
10	// (payment-date). A form (payment-form) records a new payment from those two fields
11	// (payment-form-amount / payment-form-date, submitted with payment-form-submit), refusing an
12	// incomplete one with payment-form-error.
13	//
14	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
15	// payments: { id, invoiceId, amount, date } (alongside clients / projects / invoices). This change
16	// introduces NO new audit record, so nothing is asserted through the audit channel here.
17	//
18	// The payment amount is MONEY but payment-amount is a NEW anchor, not one of the three money-format
19	// anchors the money-format spec pins exactly; so it is matched leniently (a leading "$" and a
20	// trailing ".00" both optional) — the exact presentation is not what this change pins. The date is
21	// asserted format-tolerantly the way invoice-dates does: a date rendering ("2025-06-15",
22	// "Jun 15, 2025", "15 June 2025") CONTAINS its day-of-month number. Amounts (200 / 120 / 777) and
23	// day-of-month values (15 / 28 / 09) are chosen so none is a substring of another, of a year, of a
24	// month, or of another amount — so each per-row assertion pins its own value and a swap or a leak
25	// from a sibling (or a different invoice) would fail. This test SHOULD FAIL before the change:
26	// there is no payments region, table or form on the invoice today.
27	import { test, expect } from '@playwright/test';
28	import { resetAndSeed } from '../support/seed';
29	
30	test.describe('record what a client has paid on an invoice', () => {
31	  test('an invoice shows each payment recorded on it, with its amount and date', async ({ page }) => {
32	    await resetAndSeed({
33	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
34	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
35	      invoices: [
36	        { id: 1, projectId: 1, amount: 500, status: 'SENT' },
37	        // A second invoice with its own payment, to prove the first invoice shows only ITS payments.
38	        { id: 2, projectId: 1, amount: 900, status: 'SENT' },
39	      ],
40	      payments: [
41	        { id: 1, invoiceId: 1, amount: 200, date: '2025-06-15' },
42	        { id: 2, invoiceId: 1, amount: 120, date: '2025-08-28' },
43	        // Belongs to invoice 2 — must NOT appear on invoice 1's detail page.
44	        { id: 3, invoiceId: 2, amount: 777, date: '2025-01-09' },
45	      ],
46	    });
47	
48	    await page.goto('/invoices/1');
49	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
50	
51	    // The invoice surfaces a payments region with a table of what has been paid on it.
52	    const payments = page.getByTestId('invoice-payments');
53	    await expect(payments).toBeVisible();
54	    await expect(page.getByTestId('invoice-payments-table')).toBeVisible();
55	
56	    // First payment: $200.00 on 2025-06-15 (day 15).
57	    const first = page.getByTestId('payment-row-1');
58	    await expect(first).toBeVisible();
59	    await expect(first.getByTestId('payment-amount')).toHaveText(/^\$?200(\.00)?$/);
60	    await expect(first.getByTestId('payment-date')).toContainText('15');
61	    await expect(first.getByTestId('payment-date')).not.toContainText('28');
62	
63	    // Second payment: $120.00 on 2025-08-28 (day 28). Its own amount and date, not a sibling's.
64	    const second = page.getByTestId('payment-row-2');
65	    await expect(second).toBeVisible();
66	    await expect(second.getByTestId('payment-amount')).toHaveText(/^\$?120(\.00)?$/);
67	    await expect(second.getByTestId('payment-date')).toContainText('28');
68	    await expect(second.getByTestId('payment-date')).not.toContainText('15');
69	
70	    // Payment 3 belongs to invoice 2 — it is not shown here. "Record what a client has paid on an
71	    // invoice" scopes payments to the invoice they were recorded against.
72	    await expect(page.getByTestId('payment-row-3')).toHaveCount(0);
73	    await expect(payments.getByTestId('payment-amount')).toHaveCount(2);
74	  });
75	
76	  test('records a payment through the form; it appears on the invoice with its amount and date', async ({ page }) => {
77	    // An invoice with nothing paid on it yet. RESTART IDENTITY on reset + no payments seeded means
78	    // the first payment recorded through the UI is id 1.
79	    await resetAndSeed({
80	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
81	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
82	      invoices: [{ id: 1, projectId: 1, amount: 500, status: 'SENT' }],
83	      payments: [],
84	    });
85	
86	    await page.goto('/invoices/1');
87	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
88	    await expect(page.getByTestId('invoice-payments')).toBeVisible();
89	    await expect(page.getByTestId('payment-form')).toBeVisible();
90	    // Nothing recorded yet, so no payment rows.
91	    await expect(page.getByTestId('payment-amount')).toHaveCount(0);
92	
93	    // Record what the client paid: $350.00 on 2025-07-11.
94	    await page.getByTestId('payment-form-amount').fill('350');
95	    await page.getByTestId('payment-form-date').fill('2025-07-11');
96	    await page.getByTestId('payment-form-submit').click();
97	
98	    // It appears as the first payment row, carrying the amount and date that were stored.
99	    const row = page.getByTestId('payment-row-1');
100	    await expect(row).toBeVisible();
101	    await expect(row.getByTestId('payment-amount')).toHaveText(/^\$?350(\.00)?$/);
102	    await expect(row.getByTestId('payment-date')).toContainText('11');
103	    // A valid record is not an error.
104	    await expect(page.getByTestId('payment-form-error')).toHaveCount(0);
105	  });
106	
107	  test('refuses an incomplete payment, surfacing an error and recording nothing', async ({ page }) => {
108	    await resetAndSeed({
109	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
110	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
111	      invoices: [{ id: 1, projectId: 1, amount: 500, status: 'SENT' }],
112	      payments: [],
113	    });
114	
115	    await page.goto('/invoices/1');
116	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
117	    await expect(page.getByTestId('payment-form')).toBeVisible();
118	    // No error before the user tries anything.
119	    await expect(page.getByTestId('payment-form-error')).toHaveCount(0);
120	
121	    // Submitting an empty form — no amount, no date — cannot describe a payment: it is rejected and
122	    // nothing is recorded.
123	    await page.getByTestId('payment-form-submit').click();
124	
125	    await expect(page.getByTestId('payment-form-error')).toBeVisible();
126	    await expect(page.getByTestId('payment-row-1')).toHaveCount(0);
127	    await expect(page.getByTestId('payment-amount')).toHaveCount(0);
128	
129	    // A complete payment is then accepted, clearing the error and appearing as the first row (id 1).
130	    await page.getByTestId('payment-form-amount').fill('350');
131	    await page.getByTestId('payment-form-date').fill('2025-07-11');
132	    await page.getByTestId('payment-form-submit').click();
133	
134	    const row = page.getByTestId('payment-row-1');
135	    await expect(row).toBeVisible();
136	    await expect(row.getByTestId('payment-amount')).toHaveText(/^\$?350(\.00)?$/);
137	    await expect(row.getByTestId('payment-date')).toContainText('11');
138	    await expect(page.getByTestId('payment-form-error')).toHaveCount(0);
139	  });
140	});
