1	// Acceptance tests for the change request:
2	//   "Give me a statement for a client. Put all their invoices in one place. Show the total they
3	//    still owe me."
4	//
5	// A client now has a STATEMENT. It is reached from the client's own detail page
6	// (client-detail-page, at /clients/<id>) through a control that opens it (client-statement-open) —
7	// the per-client drill-in surface the client specs already use. The statement (client-statement)
8	// gathers in ONE place EVERY invoice belonging to that client, drawn from ALL of the client's
9	// projects (an invoice belongs to a project, a project belongs to a client — see
10	// client-projects.spec.ts / all-invoices.spec.ts), in a table (client-statement-table). Each row
11	// (statement-invoice-row-<id>) surfaces, for that invoice: its id (statement-invoice-id), the
12	// amount billed (statement-invoice-amount), how much has been paid against it
13	// (statement-invoice-paid = the sum of its payments — see invoice-payments.spec.ts), how much is
14	// still left to pay on it (statement-invoice-due = amount MINUS what has been paid — the same
15	// after-payments remainder as invoice-due-amount.spec.ts), and what stage it is at
16	// (statement-invoice-status: DRAFT / SENT / PAID).
17	//
18	// The statement also shows the TOTAL the client still owes (client-outstanding-total). "Still owe"
19	// carries the app's established owed meaning (dashboard-outstanding-total / invoice-owed-sent-only
20	// .spec.ts): it counts only invoices that have actually been SENT and not yet paid, and it is net
21	// of payments — i.e. the sum of each sent-but-unpaid invoice's REMAINING balance. A DRAFT has not
22	// gone out, so it is not yet owed; a PAID invoice is already in, so it adds nothing; and another
23	// client's invoices never leak into this client's statement or total.
24	//
25	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours
26	// clients { id, name, email }, projects { id, clientId, name }, invoices { id, projectId, amount,
27	// status } and payments { id, invoiceId, amount, date }. This change introduces NO new audit
28	// record, so nothing is asserted through the audit channel here.
29	//
30	// The money values are NEW anchors, not among the three the money-format spec pins exactly, so they
31	// are matched leniently — a leading "$" and a trailing ".00" both optional — exactly as the sibling
32	// invoice-due-amount / payment-amount anchors are. Status labels are matched case-insensitively
33	// (/^sent$/i etc.) as the other invoice-stage specs do. Amounts, paid figures, remainders and the
34	// resulting owed totals are chosen so no value is a substring of another, of a wrong total a buggy
35	// implementation would produce (e.g. one that forgot to subtract payments, or counted a draft, a
36	// paid invoice, or another client's invoice), so each assertion pins its own value. This test
37	// SHOULD FAIL before the change: there is no client statement today.
38	import { test, expect } from '@playwright/test';
39	import { resetAndSeed } from '../support/seed';
40	
41	// "$300.00", "300.00" or "300" all pass — the "$" and the ".00" cents are both optional. This is
42	// how the other NEW money anchors are asserted; exact presentation is pinned by money-format.spec.
43	function money(amount: number): RegExp {
44	  return new RegExp(`^\\$?${amount}(\\.00)?$`);
45	}
46	
47	// Reach a client's statement the way a user does: open the client from the list, then open the
48	// statement from the client's detail page. The concrete URL of the statement is the feature's own
49	// choice; the stable contract is client-statement-open leading to client-statement.
50	async function openStatement(page: import('@playwright/test').Page, clientId: number) {
51	  await page.goto('/clients');
52	  await page.getByTestId(`client-open-${clientId}`).click();
