    await expect(page.getByTestId('payment-alloc-row-2').getByTestId('payment-alloc-due')).toHaveText(money(250));
    await expect(page.getByTestId('payment-alloc-row-3').getByTestId('payment-alloc-due')).toHaveText(money(90));
